def key(name):
    """Pour comparer deux noms : sans accents, sans majuscules, sans espaces ni tirets.
    "benguerir" = "Ben Guerir", "fes" = "Fès"."""
    ascii_name = unicodedata.normalize("NFKD", name).encode("ascii", "ignore").decode()
    return "".join(char for char in ascii_name.lower() if char.isalnum())


def create_cities_and_link(apps, schema_editor):
    """1. Crée les villes. 2. Chaque dossier : son ancien texte -> la ville de la liste.
    Un texte qu'on ne reconnaît pas devient une nouvelle ville (rien n'est perdu) :
    l'Admin RH pourra la renommer ou la désactiver."""
    City = apps.get_model("employees", "City")
    Employee = apps.get_model("employees", "Employee")
    cities = {key(name): City.objects.create(name=name) for name in CITIES}
    for employee in Employee.objects.all():
        text = " ".join(employee.city_text.split()) or "Casablanca"  # un ancien texte vide : la ville du siège
        city = cities.get(key(text))
        if city is None:
            city = cities[key(text)] = City.objects.create(name=text.title())
        employee.city = city
        employee.save(update_fields=["city"])


def back_to_text(apps, schema_editor):
    Employee = apps.get_model("employees", "Employee")
    for employee in Employee.objects.select_related("city"):
        employee.city_text = employee.city.name
        employee.save(update_fields=["city_text"])


